<script setup lang="ts" generic="T extends string|string[]=string">
import {computed,ref,watch,nextTick} from 'vue'
import {ChevronDown,Check} from 'lucide-vue-next'
import {useFloating} from '../../composables/useFloating'
import {useHysRootAttrs} from '../../config'
export interface HysTreeSelectNode {label:string;value:string;children?:HysTreeSelectNode[];disabled?:boolean}
const props=withDefaults(defineProps<{modelValue:T;nodes:HysTreeSelectNode[];placeholder?:string;disabled?:boolean;multiple?:boolean;clearable?:boolean;searchable?:boolean;leafOnly?:boolean}>(),{searchable:true})
const emit=defineEmits<{'update:modelValue':[value:T];change:[value:T];clear:[]}>(),hysRootAttrs=useHysRootAttrs(),trigger=ref<HTMLElement>(),panel=ref<HTMLElement>(),searchInput=ref<HTMLInputElement>(),search=ref(''),active=ref(0)
const {open,style,show,close}=useFloating(trigger,panel,{matchWidth:true})
function flatten(nodes:HysTreeSelectNode[],depth=0,parentDisabled=false):{node:HysTreeSelectNode;depth:number}[]{return nodes.flatMap(n=>[{node:{...n,disabled:parentDisabled||n.disabled},depth},...flatten(n.children||[],depth+1,parentDisabled||n.disabled)])}
const all=computed(()=>flatten(props.nodes)),items=computed(()=>all.value.filter(x=>x.node.label.toLocaleLowerCase().includes(search.value.toLocaleLowerCase()))),enabled=computed(()=>items.value.filter(x=>!x.node.disabled&&(!props.leafOnly||!x.node.children?.length)))
const values=computed<string[]>(()=>Array.isArray(props.modelValue)?props.modelValue as string[]:[props.modelValue as string].filter(Boolean)),multiple=computed(()=>props.multiple||Array.isArray(props.modelValue))
const selected=computed(()=>all.value.filter(x=>values.value.includes(x.node.value)).map(x=>x.node.label).join('、'))
watch(search,()=>active.value=0);watch(()=>props.disabled,v=>{if(v)close()})
async function expand(){if(props.disabled)return;search.value='';await show();await nextTick();searchInput.value?.focus()}
function update(value:string|string[]){emit('update:modelValue',value as T);emit('change',value as T)}
function pick(node:HysTreeSelectNode){if(props.disabled||node.disabled||props.leafOnly&&node.children?.length)return;update(multiple.value?(values.value.includes(node.value)?values.value.filter(x=>x!==node.value):[...values.value,node.value]):node.value);if(!multiple.value)close(true)}
function keys(e:KeyboardEvent){if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();active.value=e.key==='Home'?0:e.key==='End'?enabled.value.length-1:Math.max(0,Math.min(enabled.value.length-1,active.value+(e.key==='ArrowDown'?1:-1)));panel.value?.querySelectorAll<HTMLElement>('[data-enabled]')[active.value]?.scrollIntoView({block:'nearest'})}else if(e.key==='Enter'&&enabled.value[active.value]){e.preventDefault();pick(enabled.value[active.value].node)}else if(e.key==='Escape'){e.preventDefault();close(true)}}
</script>
<template><div v-bind="hysRootAttrs" class="hys-ui-v4-relative"><button ref="trigger" type="button" class="hys-ui-v4-control hys-ui-pf-select-trigger" :disabled="disabled" aria-haspopup="listbox" :aria-expanded="open" @click="open?close():expand()" @keydown.down.prevent="expand"><span>{{selected||placeholder||'选择节点'}}</span><ChevronDown :size="16" class="hys-ui-pf-select-chevron"/></button><Teleport to="body"><div v-if="open" ref="panel" v-bind="hysRootAttrs" class="hys-ui-v4-menu hys-ui-pf-select-menu hys-ui-pf-tree-select-menu" :style="style" @keydown="keys"><input v-if="searchable" ref="searchInput" v-model="search" class="hys-ui-v4-control" placeholder="搜索节点" aria-label="搜索节点"/><div class="hys-ui-v4-scroll" role="listbox" :aria-multiselectable="multiple||undefined" aria-label="节点选择"><button v-for="item in items" :key="item.node.value" type="button" role="option" :aria-selected="values.includes(item.node.value)" :disabled="item.node.disabled||leafOnly&&!!item.node.children?.length" :data-enabled="item.node.disabled||leafOnly&&item.node.children?.length?undefined:''" class="hys-ui-v4-option" :class="{'hys-ui-v4-active':enabled[active]?.node.value===item.node.value}" :style="{paddingLeft:(12+item.depth*16)+'px'}" @click="pick(item.node)"><slot name="option" :node="item.node">{{item.node.label}}</slot><Check v-if="values.includes(item.node.value)" :size="15"/></button><p v-if="!items.length">无匹配节点</p></div><button v-if="clearable&&values.length" type="button" class="hys-ui-v4-option" @click="update(multiple?[]:'');emit('clear');close(true)">清空选择</button></div></Teleport></div></template>
